/**
 * HMAC Signature Module for CCS Reports
 * 
 * Replaces fake SHA-256 "signature" with real HMAC-SHA256 using server private key.
 * This proves the report was generated by our server, not just that content hasn't changed.
 */

import crypto from 'crypto';

// Server private key for HMAC signing (MUST be kept secret)
// In production, load from environment or secret manager
const HMAC_SECRET = process.env.CCS_HMAC_SECRET || 'dev-only-secret-change-in-production';

/**
 * Generate HMAC-SHA256 signature for a report
 * 
 * @param {Object} reportData - The report data to sign
 * @param {string} reportData.report_id - Report UUID
 * @param {string} reportData.api_key - API key that generated the report
 * @param {number} reportData.timestamp - Report generation timestamp
 * @param {Object} reportData.summary - Report summary (risks, tools, etc.)
 * @returns {string} HMAC-SHA256 signature in hex format
 */
export function signReport(reportData) {
  // Create canonical string from report data
  const canonical = [
    reportData.report_id,
    reportData.api_key,
    reportData.timestamp,
    JSON.stringify(reportData.summary),
    JSON.stringify(reportData.tools)
  ].join(':');
  
  // Generate HMAC-SHA256 signature
  const hmac = crypto.createHmac('sha256', HMAC_SECRET);
  hmac.update(canonical);
  return hmac.digest('hex');
}

/**
 * Verify HMAC-SHA256 signature for a report
 * 
 * @param {Object} reportData - The report data to verify
 * @param {string} signature - The signature to verify
 * @returns {boolean} True if signature is valid
 */
export function verifySignature(reportData, signature) {
  const expected = signReport(reportData);
  
  // Constant-time comparison to prevent timing attacks
  if (expected.length !== signature.length) {
    return false;
  }
  
  return crypto.timingSafeEqual(
    Buffer.from(expected, 'hex'),
    Buffer.from(signature, 'hex')
  );
}

/**
 * Generate a verification token for public verify_url
 * 
 * This is a SHORT-LIVED token that proves the report exists without exposing full data.
 * Valid for 24 hours, single-use.
 * 
 * @param {string} reportId - Report UUID
 * @param {string} apiKey - API key that owns the report
 * @returns {Object} { token, expires }
 */
export function generateVerifyToken(reportId, apiKey) {
  const expires = Date.now() + 24 * 60 * 60 * 1000; // 24 hours
  
  const payload = `${reportId}:${apiKey}:${expires}`;
  const hmac = crypto.createHmac('sha256', HMAC_SECRET);
  hmac.update(payload);
  const token = hmac.digest('base64url');
  
  return { token, expires };
}

/**
 * Verify a verification token
 * 
 * @param {string} reportId - Report UUID
 * @param {string} apiKey - API key that owns the report
 * @param {string} token - Token to verify
 * @param {number} expires - Expiration timestamp
 * @returns {boolean} True if token is valid and not expired
 */
export function verifyToken(reportId, apiKey, token, expires) {
  // Check expiration
  if (Date.now() > expires) {
    return false;
  }
  
  // Regenerate expected token
  const payload = `${reportId}:${apiKey}:${expires}`;
  const hmac = crypto.createHmac('sha256', HMAC_SECRET);
  hmac.update(payload);
  const expected = hmac.digest('base64url');
  
  // Constant-time comparison
  if (expected.length !== token.length) {
    return false;
  }
  
  return crypto.timingSafeEqual(
    Buffer.from(expected),
    Buffer.from(token)
  );
}

export default {
  signReport,
  verifySignature,
  generateVerifyToken,
  verifyToken
};
